import { useState } from "react";
import axios from "axios";
import { motion, AnimatePresence } from "framer-motion";


export default function App() {
  const [code, setCode] = useState("");
  const [explanation, setExplanation] = useState("");
  const [loading, setLoading] = useState(false);

  const explainCode = async () => {
    if (!code.trim()) return;

    setLoading(true);
    setExplanation("");

    try {
      const res = await axios.post("http://127.0.0.1:8000/explain", {
        code,
      });

      setExplanation(res.data.explanation);
    } catch (err) {
      setExplanation("Something went wrong. Try again.");
    }

    setLoading(false);
  };

  return (
<div className="min-h-screen bg-gradient-to-br from-slate-900 via-slate-900 to-blue-900 px-6 py-12">
      <motion.div
  initial={{ opacity: 0, y: 20 }}
  animate={{ opacity: 1, y: 0 }}
  transition={{ duration: 0.6 }}
  className="w-full max-w-4xl space-y-6"
>


        {/* Header */}
        <div className="text-center space-y-3 mb-10">
  <h1 className="text-5xl font-bold text-white tracking-tight">
    🤖 AI Code Explainer
  </h1>
  <p className="text-slate-400 max-w-xl mx-auto">
    Paste your code and instantly understand what it does — explained clearly, step by step.
  </p>
</div>


        {/* Code Input */}
        <div className="bg-slate-800/80 backdrop-blur rounded-2xl p-6 border border-slate-700 shadow-xl space-y-4">

  <textarea
    className="w-full h-56 bg-transparent text-slate-100 font-mono text-sm outline-none resize-none"
    placeholder="Paste your code here..."
    value={code}
    onChange={(e) => setCode(e.target.value)}
  />

  <div className="flex justify-end">
    <motion.button
      whileHover={{ scale: 1.05 }}
      whileTap={{ scale: 0.95 }}
      onClick={explainCode}
      disabled={loading}
      className="px-6 py-3 rounded-xl bg-blue-500 hover:bg-blue-600 transition text-white font-semibold disabled:opacity-50"
    >
      {loading ? "AI is thinking..." : "Explain Code"}
    </motion.button>
  </div>

</div>

        </motion.div>

        {/* Action Button */}
        <motion.button
  whileHover={{ scale: 1.05 }}
  whileTap={{ scale: 0.95 }}
  onClick={explainCode}
  disabled={loading}
  className="px-6 py-3 rounded-lg bg-blue-500 hover:bg-blue-600 transition text-white font-semibold disabled:opacity-50"
>
  {loading ? "AI is thinking..." : "Explain Code"}
</motion.button>


        {/* Output */}
        <AnimatePresence>
  {explanation && (
    <motion.div
  initial={{ opacity: 0, y: 10 }}
  animate={{ opacity: 1, y: 0 }}
  transition={{ duration: 0.4 }}
  className="mt-10 bg-slate-800/90 backdrop-blur rounded-2xl p-8 border border-slate-700 shadow-2xl"
>
  <h3 className="text-xl font-semibold mb-4 text-white flex items-center gap-2">
    🧠 Explanation
  </h3>

  <p className="text-slate-300 whitespace-pre-wrap leading-relaxed">
    {explanation}
  </p>
</motion.div>

  )}
</AnimatePresence>
<div className="absolute inset-0 -z-10">
  <div className="absolute top-20 left-1/2 w-[500px] h-[500px] bg-blue-500/20 blur-[120px] -translate-x-1/2"></div>
</div>


      </div>
  );
}
